<?php
require_once __DIR__.'/_data.php';
$db=storefront_db();$customer=$db?marketplace_customer($db):null;if(!$customer)legacy_redirect('masuk?next=alamat-saya');$cid=(int)$customer['id'];$error='';
if(is_post()){
 if(!CSRF::verify())$error='Sesi formulir kedaluwarsa.';else{
  try{
   $action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
   if($action==='delete'&&$id>0){$db->prepare("DELETE FROM customer_addresses WHERE id=? AND customer_id=?")->execute([$id,$cid]);flash('success','Alamat dihapus.');legacy_redirect('alamat-saya');}
   if($action==='default'&&$id>0){$db->beginTransaction();$db->prepare("UPDATE customer_addresses SET is_default=0 WHERE customer_id=?")->execute([$cid]);$db->prepare("UPDATE customer_addresses SET is_default=1 WHERE id=? AND customer_id=?")->execute([$id,$cid]);$db->commit();flash('success','Alamat utama diperbarui.');legacy_redirect('alamat-saya');}
   $label=trim((string)($_POST['label']??'Rumah'));$name=trim((string)($_POST['recipient_name']??''));$phone=preg_replace('/[^0-9+]/','',(string)($_POST['recipient_phone']??''));$address=trim((string)($_POST['address']??''));$destinationId=(int)($_POST['destination_id']??0);$destinationLabel=trim((string)($_POST['destination_label']??''));
   if($name===''||strlen(preg_replace('/\D+/','',$phone))<9||mb_strlen($address)<8||$destinationId<=0||$destinationLabel==='')throw new InvalidArgumentException('Lengkapi penerima, alamat, dan pilih wilayah dari hasil RajaOngkir.');
   $isDefault=!empty($_POST['is_default'])?1:0;$countStmt=$db->prepare("SELECT COUNT(*) FROM customer_addresses WHERE customer_id=?");$countStmt->execute([$cid]);if((int)$countStmt->fetchColumn()===0)$isDefault=1;
   $db->beginTransaction();if($isDefault)$db->prepare("UPDATE customer_addresses SET is_default=0 WHERE customer_id=?")->execute([$cid]);
   $stmt=$db->prepare("INSERT INTO customer_addresses(customer_id,label,recipient_name,recipient_phone,address,destination_id,destination_label,province,city,district,subdistrict,postal_code,is_default,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())");$stmt->execute([$cid,$label?:'Alamat',$name,$phone,$address,$destinationId,$destinationLabel,trim((string)($_POST['province']??''))?:null,trim((string)($_POST['city']??''))?:null,trim((string)($_POST['district']??''))?:null,trim((string)($_POST['subdistrict']??''))?:null,trim((string)($_POST['postal_code']??''))?:null,$isDefault]);$db->commit();flash('success','Alamat berhasil disimpan.');legacy_redirect('alamat-saya');
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}
 }
}
$addresses=marketplace_customer_addresses($db,$cid);$pageTitle='Alamat Saya';$activePage='account';require __DIR__.'/_header.php';$success=flash('success');
