n-danger-soft" type="submit"><i class="bi bi-trash3"></i> Hapus</button></form></div></div><?php endforeach;else:?><div class="account-empty"><i class="bi bi-geo"></i><h3>Belum ada alamat tersimpan</h3><p>Tambahkan alamat pertama Anda di formulir sebelah.</p></div><?php endif;?></div></section></div><aside class="checkout-box address-add-card"><div class="checkout-box-title"><span><i class="bi bi-plus-lg"></i></span><div><small>ALAMAT BARU</small><h2>Tambah Alamat</h2></div></div><form method="post" class="account-form" id="savedAddressForm" data-destination-url="<?=e(legacy_base_url('store/api/destination-search.php'))?>"><?=CSRF::input()?><input type="hidden" name="action" value="save"><input type="hidden" name="destination_id" id="saDestinationId"><input type="hidden" name="destination_label" id="saDestinationLabel"><input type="hidden" name="province" id="saProvince"><input type="hidden" name="city" id="saCity"><input type="hidden" name="district" id="saDistrict"><input type="hidden" name="subdistrict" id="saSubdistrict"><label>Label Alamat<input name="label" placeholder="Rumah / Kantor" value="Rumah"></label><label>Nama Penerima<input name="recipient_name" required value="<?=e($customer['name'])?>"></label><label>WhatsApp<input name="recipient_phone" required value="<?=e($customer['phone']??'')?>"></label><label>Alamat Lengkap<textarea name="address" required rows="3"><?=e($customer['address']??'')?></textarea></label><label>Cari Wilayah RajaOngkir<div class="destination-search-wrap"><i class="bi bi-geo-alt"></i><input type="search" id="saSearch" placeholder="Kecamatan / kelurahan / kota" autocomplete="off"><div class="destination-results" id="saResults" hidden></div></div></label><label>Kode Pos<input name="postal_code" id="saPostal" inputmode="numeric"></label><label class="check-row"><input type="checkbox" name="is_default" value="1"><span>Jadikan alamat utama</span></label><button class="btn-primary-store full" type="submit"><i class="bi bi-save"></i> Simpan Alamat</button></form></aside></section></main>
<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('#savedAddressForm'),q=document.querySelector('#saSearch'),r=document.querySelector('#saResults');if(!f||!q||!r)return;let t;const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]));q.addEventListener('input',()=>{clearTimeout(t);const v=q.value.trim();if(v.length<3){r.hidden=true;return}t=setTimeout(async()=>{try{const x=await fetch(f.dataset.destinationUrl+'?q='+encodeURIComponent(v));const j=await x.json();const rows=Array.isArray(j.data)?j.data:[];r.innerHTML=rows.map((a,i)=>`<button type="button" data-i="${i}" class="destination-result-item"><i class="bi bi-geo-alt"></i><span><b>${esc(a.label)}</b><small>${esc([a.province,a.city,a.district,a.subdistrict,a.zip_code].filter(Boolean).join(' • '))}</small></span></button>`).join('')||'<div class="destination-empty">Wilayah tidak ditemukan.</div>';r.hidden=false;r.querySelectorAll('button').forEach(b=>b.onclick=()=>{const a=rows[+b.dataset.i];q.value=a.label;document.querySelector('#saDestinationId').value=a.id;document.querySelector('#saDestinationLabel').value=a.label;document.querySelector('#saProvince').value=a.province||'';document.querySelector('#saCity').value=a.city||'';document.querySelector('#saDistrict').value=a.district||'';document.querySelector('#saSubdistrict').value=a.subdistrict||'';document.querySelector('#saPostal').value=a.zip_code||'';r.hidden=true})}catch(e){r.innerHTML='<div class="destination-empty error">Gagal mencari wilayah.</div>';r.hidden=false}},400)});});</script>
